class RUIndexParseError(Exception):
    """
    Raised when could not parse rmod index from rmod name.
    """


class NotAllMandatoryFilesPresent(Exception):
    """
    Raised when not all mandatory file are present in collected snapshot.
    """


class NoMandatoryItems(Exception):
    """
    Raised when there is no mandatory items specified.
    """
    pass


class SwStreamNotSupported(Exception):
    """
    Raised when sw stream is not supported.
    """


class JournalFilesNotFoundInThirdDepthOfSnapshot(Exception):
    """
    Raised when there is no journal.txt file
    in third depth of collected and unpacked snapshot
    during searching for journal.txt files.
    """


class SnapshotFileListError(Exception):
    """
    Raised when format of snapshot file list is not correct.
    """


class FileNotFoundInSnapshot(Exception):
    """
    Raised when particular file is not found in snapshot.
    """


class ArchiveExtractionError(Exception):
    """
    Raised when archive extraction has failed.
    """


class SnapshotCollectionError(Exception):
    """
    Raised when snapshot collection has failed.
    """


class SnapshotCollectionTimeout(Exception):
    """
    Raised when snapshot collection exceeds the specified time.
    """


class MissingParametrs(Exception):
    """
    Raised when not all mandatory parameters are specified.
    """
